    {
     "term": "Common Stock",
     "def": "An equity security representing ownership in a corporation; carries voting rights, limited liability, and a residual (last) claim on assets and earnings."
    },
    {
     "term": "Preferred Stock",
     "def": "An equity security paying a fixed dividend with priority over common stock for dividends and liquidation; usually non-voting and issued at $100 par."
    },
    {
     "term": "Limited Liability",
     "def": "The principle that a shareholder's maximum loss is the amount invested; personal assets are shielded from the corporation's debts."
    },
    {
     "term": "Residual Claim",
     "def": "The right of common stockholders to assets in a liquidation only AFTER creditors and preferred stockholders are paid — making them last in line."
    },
    {
     "term": "Preemptive Right",
     "def": "The right of existing common shareholders to buy newly issued shares first, in proportion to their holdings, to avoid dilution of their ownership percentage."
    },
    {
     "term": "Statutory Voting",
     "def": "A voting method where a shareholder casts up to one vote per share for EACH director seat but cannot concentrate votes; favors majority shareholders."
    },
    {
     "term": "Cumulative Voting",
     "def": "A voting method allowing a shareholder to multiply shares by open seats and concentrate all votes on one candidate; favors minority shareholders."
    },
    {
     "term": "Cumulative Preferred",
     "def": "Preferred stock on which omitted (missed) dividends accumulate as arrears and must be paid in full, plus the current dividend, before common dividends."
    },
    {
     "term": "Participating Preferred",
     "def": "Preferred stock that can receive extra dividends above its stated rate when the company has strong earnings."
    },
    {
     "term": "Convertible Preferred",
     "def": "Preferred stock exchangeable for a fixed number of common shares; usually carries a lower stated rate because of the conversion upside."
    },
    {
     "term": "Callable Preferred",
     "def": "Preferred stock the issuer may redeem at a set call price after a call date; carries a higher stated rate to compensate for call risk."
    },
    {
     "term": "Rights (Subscription Rights)",
     "def": "Short-term instruments giving existing shareholders the option to buy new shares at a discount to market, used to honor preemptive rights."
    },
    {
     "term": "Warrant",
     "def": "A long-term instrument allowing purchase of stock at a price above market at issuance; usually attached to a bond or preferred offering as a sweetener."
    },
    {
     "term": "American Depositary Receipt (ADR)",
     "def": "A negotiable U.S. certificate representing shares of a foreign company, trading and paying dividends in U.S. dollars; subject to currency risk."
    },
    {
     "term": "Forward Split",
     "def": "A stock split that increases share count and lowers price (e.g., 2-for-1) without changing total value or proportional ownership."
    },
    {
     "term": "Reverse Split",
     "def": "A stock split that decreases share count and raises price (e.g., 1-for-10), often to lift a low share price or meet listing minimums."
    },
    {
     "term": "Ex-Dividend Date",
     "def": "The first day a stock trades without the upcoming dividend; equals the record date under T+1, and the price drops by the dividend amount at the open."
    },
    {
     "term": "Qualified Dividend",
     "def": "A dividend meeting IRS holding-period rules, taxed at favorable long-term capital-gains rates rather than ordinary income rates."
    }
