   "glossary": [
    {
     "term": "General Obligation (GO) Bond",
     "def": "A municipal bond backed by the full faith, credit, and taxing power of the issuer; usually requires voter approval and is subject to debt limits."
    },
    {
     "term": "Revenue Bond",
     "def": "A municipal bond repaid solely from the revenues of a specific project or facility (e.g., tolls, user fees); not backed by taxing power and not subject to debt limits."
    },
    {
     "term": "Ad Valorem Tax",
     "def": "A tax based on the assessed value of property; the primary source of repayment for local GO bonds."
    },
    {
     "term": "Debt Service",
     "def": "The total principal and interest payments an issuer must make on its outstanding debt."
    },
    {
     "term": "Debt Service Coverage Ratio (DSCR)",
     "def": "Net revenue available divided by annual debt service; the key credit measure for a revenue bond (higher is safer)."
    },
    {
     "term": "Double-Barreled Bond",
     "def": "A revenue bond that is additionally backed by the issuer's taxing power; analyzed as a GO bond."
    },
    {
     "term": "Feasibility Study",
     "def": "An independent projection of whether a project will generate enough revenue to support a proposed revenue bond."
    },
    {
     "term": "TAN / RAN / BAN",
     "def": "Tax, Revenue, and Bond Anticipation Notes — short-term municipal notes repaid from future tax collections, future revenues, or the proceeds of a future bond issue, respectively."
    },
    {
     "term": "TRAN / CLN",
     "def": "Tax & Revenue Anticipation Note (repaid from both taxes and revenues) and Construction Loan Note (repaid by permanent financing once a project is built)."
    },
    {
     "term": "Triple-Tax-Free",
     "def": "A municipal bond whose interest is exempt from federal, state, and local income tax — typically an in-state bond for the resident, or any territorial bond (Puerto Rico, Guam, USVI)."
    },
    {
     "term": "Tax-Equivalent Yield (TEY)",
     "def": "The yield a taxable bond must offer to match a muni's tax-free yield: muni yield ÷ (1 − marginal tax rate)."
    },
    {
     "term": "Industrial Development Bond (IDB) / Private Activity Bond (PAB)",
     "def": "A municipal bond financing a facility for a private user; backed by that user's lease payments, and its interest is an AMT tax preference item."
    },
    {
     "term": "Alternative Minimum Tax (AMT)",
     "def": "A parallel federal tax calculation; interest on private activity bonds is a tax preference item added back when computing AMT."
    },
    {
     "term": "529 Plan",
     "def": "A state-sponsored, tax-advantaged education savings plan; after-tax contributions grow tax-deferred and qualified education withdrawals are federally tax-free."
    },
    {
     "term": "ABLE Account",
     "def": "A tax-advantaged savings account for individuals disabled before age 26, allowing tax-free withdrawals for qualified disability expenses without jeopardizing means-tested benefits."
    },
    {
     "term": "MSRB",
     "def": "Municipal Securities Rulemaking Board — writes rules for municipal dealers and advisors but has no enforcement authority (FINRA and the SEC enforce)."
    },
    {
     "term": "Official Statement (OS)",
     "def": "The disclosure document for a new municipal offering (the muni equivalent of a prospectus), detailing terms, repayment source, use of proceeds, and tax status."
    }
   ],
